package com.yuegang.zhihui.ai.infrastructure;import com.yuegang.zhihui.ai.domain.*;import io.micrometer.core.instrument.*;public final class MeasuredModelGateway implements ModelGateway{private final ModelGateway delegate;private final Timer duration;private final DistributionSummary promptTokens,completionTokens;public MeasuredModelGateway(ModelGateway d,MeterRegistry m){delegate=d;duration=Timer.builder("ygh.ai.model.duration").description("Complete model response duration").register(m);promptTokens=DistributionSummary.builder("ygh.ai.prompt.tokens").register(m);completionTokens=DistributionSummary.builder("ygh.ai.completion.tokens").register(m);}public String answer(String system,String user){return answerWithSources(system,user).text();}public ModelAnswer answerWithSources(String system,String user){promptTokens.record(tokens(system)+tokens(user));return duration.record(()->{ModelAnswer answer=delegate.answerWithSources(system,user);completionTokens.record(tokens(answer.text()));return answer;});}public String modelName(){return delegate.modelName();}public boolean available(){return delegate.available();}public boolean supportsWebSearch(){return delegate.supportsWebSearch();}private static int tokens(String x){return Math.max(1,x==null?0:x.codePointCount(0,x.length())/2);}}
